<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount} from 'vue'
import {transportState as state,transportRoadStatus,transportPosition} from '@/api/transport'
import {farmZones} from '@/data/farm'
const props=defineProps<{overview?:boolean;preview?:string[]}>()
const emit=defineEmits<{(e:'open'):void}>()
const position=ref({x:1400,y:300});let frame=0
onMounted(()=>{const tick=()=>{position.value=transportPosition();frame=requestAnimationFrame(tick)};frame=requestAnimationFrame(tick)});onBeforeUnmount(()=>cancelAnimationFrame(frame))
const point=(id:string)=>state.value?.stops.find(n=>n.id===id)||{x:0,y:0}
const roadLegal=(id:string)=>transportRoadStatus.value.find(r=>r.id===id)?.legal===true
const route=computed(()=>props.preview||state.value?.tasks.find(t=>['RUNNING','BLOCKED','PAUSED','WAIT_LOAD','WAIT_UNLOAD'].includes(t.status))?.route||[])
const routePoints=computed(()=>route.value.map(id=>`${point(id).x},${point(id).y}`).join(' '))
</script>
<template><svg v-if="state" class="transport-map" :class="{overview}" viewBox="0 0 1536 1024" :preserveAspectRatio="overview?'xMidYMid meet':'none'" aria-label="批准道路与自动运输车"><g v-if="overview" class="building-keepout"><rect x="1080" y="270" width="170" height="70" rx="7"/><rect x="1380" y="285" width="130" height="75" rx="7"/><text x="1165" y="310">分选包装中心</text><text x="1445" y="325">仓库建筑</text></g><g v-if="overview" class="parcels"><polygon v-for="zone in farmZones" :key="zone.id" :points="zone.polygon.map(p=>p.join(',')).join(' ')"/><text v-for="zone in farmZones" :key="zone.id+'label'" :x="zone.polygon.reduce((s,p)=>s+p[0],0)/zone.polygon.length" :y="zone.polygon.reduce((s,p)=>s+p[1],0)/zone.polygon.length">{{zone.crop}}</text></g><g class="roads"><line v-for="road in state.roads" :key="road.id" :class="{closed:road.blocked||!roadLegal(road.id)}" :x1="point(road.a).x" :y1="point(road.a).y" :x2="point(road.b).x" :y2="point(road.b).y"/></g><polyline v-if="routePoints" :points="routePoints" class="planned-route"/><g v-for="stop in state.stops" :key="stop.id" class="stop"><circle :cx="stop.x" :cy="stop.y" r="7"><title>{{stop.name}}</title></circle><text v-if="overview && [route[0],route[route.length-1],'warehouse','charge'].includes(stop.id) && Math.hypot(position.x-stop.x,position.y-stop.y)>30" :x="stop.x" :y="stop.y-15">{{stop.name}}</text></g><g v-for="obstacle in state.obstacles" :key="obstacle.id"><circle :cx="obstacle.x" :cy="obstacle.y" :r="obstacle.radius+9" class="obstacle-margin"/><circle :cx="obstacle.x" :cy="obstacle.y" :r="obstacle.radius" class="obstacle"/></g><g class="cart-position" :transform="`translate(${position.x} ${position.y})`" @click.stop="emit('open')" role="button" tabindex="0" aria-label="打开自动运输车控制" @keydown.enter="emit('open')"><circle r="15" fill="transparent"/><circle r="9" fill="#2c735b15" stroke="#78a68b" stroke-dasharray="2 2" stroke-width="1"/><g :transform="`rotate(${state.heading*180/Math.PI})`" class="cart-orientation"><g transform="scale(.34)"><rect x="-18" y="-15" width="36" height="30" rx="7" class="cart-body"/><rect x="-11" y="-18" width="9" height="5" rx="2" class="wheel"/><rect x="-11" y="13" width="9" height="5" rx="2" class="wheel"/><rect x="7" y="-18" width="9" height="5" rx="2" class="wheel"/><rect x="7" y="13" width="9" height="5" rx="2" class="wheel"/><rect x="-12" y="-10" width="21" height="20" rx="3" class="cargo"/><path d="m12-6 7 6-7 6" class="cart-front"/></g></g><text y="-18" class="cart-name">运输车 01</text><title>{{state.emergency?'已急停':'点击打开运输控制'}}</title></g></svg></template>
<style scoped>.transport-map{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}.transport-map.overview{position:relative;min-height:300px;aspect-ratio:3/2;display:block;background:#f2f7f3;border:1px solid #dfeae2;border-radius:12px}.parcels polygon{fill:#d7e8d8;stroke:#a8c6ac;stroke-width:2}.parcels text{font:16px var(--font-sans);fill:#6d9476;text-anchor:middle}.roads line{stroke:#d6e0d6;stroke-width:24;stroke-linecap:round}.roads line.closed{stroke:#bda89b;stroke-dasharray:8 9;opacity:.6}.planned-route{stroke:#338569;stroke-width:4;fill:none;stroke-dasharray:10 7}.stop circle{fill:white;stroke:#76a389;stroke-width:3}.stop text{font:12px var(--font-sans);fill:#50735b;text-anchor:middle;paint-order:stroke;stroke:#f2f7f3;stroke-width:4}.cart-position{pointer-events:auto;cursor:pointer;outline:none}.cart-position:focus .cart-body{stroke:#fff8a1;stroke-width:5}.cart-body{fill:#2c735b;stroke:white;stroke-width:2;filter:drop-shadow(0 3px 4px #173d3866)}.wheel{fill:#263735}.cargo{fill:#c7d9a4;stroke:#eaf2de;stroke-width:1}.cart-front{fill:#ffdf81}.cart-name{font:600 14px var(--font-sans);fill:#fff;text-anchor:middle;paint-order:stroke;stroke:#245b47;stroke-width:4}.obstacle{fill:#cd9464;stroke:#fff;stroke-width:2}.obstacle-margin{fill:#dc936624;stroke:#c38f62;stroke-width:1;stroke-dasharray:4 5}</style>
<style scoped>.cart-orientation{transition:transform .45s linear}@media(prefers-reduced-motion:reduce){.cart-orientation{transition:none}}</style><style scoped>.building-keepout rect{fill:#cfd9d5;stroke:#9eafa6;stroke-width:2}.building-keepout text{fill:#6a7e73;font:12px var(--font-sans);text-anchor:middle}</style><style scoped>.overview .stop text{font-size:24px}.overview .cart-name{font-size:27px}.overview .parcels text{font-size:25px}</style><style scoped>.transport-map.overview{height:auto;min-height:0;width:100%;aspect-ratio:3/2}.overview .stop text{font-size:25px}.overview .cart-name{font-size:30px}</style>